"use client";

import { cn } from "cn";
import { format } from "date-fns";
import type { Locale } from "date-fns";
import { CalendarDays } from "lucide-react";
import * as React from "react";
import type { Matcher } from "react-day-picker";

import { Button } from "./button";
import { Calendar } from "./calendar";
import { Popover, PopoverContent, PopoverTrigger } from "./popover";

interface CalendarOptions {
  disabledDates?: Matcher | Matcher[];
  startMonth?: Date;
  endMonth?: Date;
}

export type DatePickerProps = CalendarOptions & {
  id?: string;
  label: string;
  placeholder?: string;
  clearable?: boolean;
  value?: Date;
  defaultValue?: Date;
  onValueChange?: (date: Date | undefined) => void;
  locale?: Locale;
  dateFormat?: string;
  disabled?: boolean;
  readOnly?: boolean;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  className?: string;
};

export const DatePicker = (props: DatePickerProps) => {
  const {
    id,
    label,
    placeholder = "Select a date",
    clearable = false,
    value,
    defaultValue,
    onValueChange,
    locale,
    dateFormat = "PPP",
    disabled,
    readOnly,
    open,
    defaultOpen = false,
    onOpenChange,
    className,
    ...calendarOptions
  } = props;
  const controlled = Object.hasOwn(props, "value");
  const [internal, setInternal] = React.useState(defaultValue);
  const [internalOpen, setInternalOpen] = React.useState(defaultOpen);
  const current = controlled ? value : internal;
  const isOpen = open === undefined ? internalOpen : open;
  const setOpen = (next: boolean) => {
    if (open === undefined) {
      setInternalOpen(next);
    }
    onOpenChange?.(next);
  };
  const selectDate = (date?: Date) => {
    if (!controlled) {
      setInternal(date);
    }
    onValueChange?.(date);
  };

  return (
    <div data-slot="date-picker" className="grid min-w-0 gap-1.5">
      <span id={id ? `${id}-label` : undefined} className="text-sm font-medium">
        {label}
      </span>
      <Popover open={isOpen} onOpenChange={setOpen}>
        <PopoverTrigger
          disabled={disabled}
          aria-labelledby={id ? `${id}-label` : undefined}
          aria-label={id ? undefined : label}
          className={cn(
            "inline-flex h-9 min-w-0 items-center justify-start gap-2 rounded-md border border-input bg-background px-3 text-sm font-normal shadow-xs outline-none hover:bg-accent focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 dark:bg-input/30",
            className
          )}
        >
          <CalendarDays aria-hidden="true" className="size-4 shrink-0" />
          <span className={cn("truncate", !current && "text-muted-foreground")}>
            {current ? format(current, dateFormat, { locale }) : placeholder}
          </span>
        </PopoverTrigger>
        <PopoverContent
          align="start"
          className="w-auto max-w-[calc(100vw-1rem)] p-2"
        >
          <Calendar
            mode="single"
            locale={locale}
            selected={current}
            disabled={readOnly ? () => true : calendarOptions.disabledDates}
            startMonth={calendarOptions.startMonth}
            endMonth={calendarOptions.endMonth}
            onSelect={(date) => {
              selectDate(date);
              setOpen(false);
            }}
          />
          {clearable && current && !readOnly ? (
            <Button
              type="button"
              variant="ghost"
              className="mt-1 w-full"
              onClick={() => {
                selectDate();
                setOpen(false);
              }}
            >
              Clear date
            </Button>
          ) : null}
        </PopoverContent>
      </Popover>
    </div>
  );
};

import {
  addDays,
  endOfMonth,
  endOfWeek,
  isAfter,
  isBefore,
  isSameDay,
  startOfDay,
  startOfMonth,
  startOfWeek,
  subDays,
  subMonths,
} from "date-fns";
import type { DateRange } from "react-day-picker";

export type DateShortcut =
  | "last7Days"
  | "last14Days"
  | "last30Days"
  | "thisWeek"
  | "lastWeek"
  | "thisMonth"
  | "lastMonth";

const asCalendarDay = (date: Date) =>
  new Date(date.getFullYear(), date.getMonth(), date.getDate());

export const resolveDateShortcut = (
  shortcut: DateShortcut,
  today: Date,
  weekStartsOn: 0 | 1 | 2 | 3 | 4 | 5 | 6 = 1
): { from: Date; to: Date } => {
  const current = new Date(
    today.getFullYear(),
    today.getMonth(),
    today.getDate()
  );
  const dayCounts = { last14Days: 14, last30Days: 30, last7Days: 7 } as const;
  if (
    shortcut === "last7Days" ||
    shortcut === "last14Days" ||
    shortcut === "last30Days"
  ) {
    const count = dayCounts[shortcut];
    return { from: subDays(current, count - 1), to: current };
  }

  const weekStart = startOfWeek(current, { weekStartsOn });
  switch (shortcut) {
    case "thisWeek": {
      return {
        from: weekStart,
        to: asCalendarDay(endOfWeek(current, { weekStartsOn })),
      };
    }
    case "lastWeek": {
      const previous = subDays(weekStart, 1);
      return {
        from: startOfWeek(previous, { weekStartsOn }),
        to: asCalendarDay(endOfWeek(previous, { weekStartsOn })),
      };
    }
    case "thisMonth": {
      return {
        from: startOfMonth(current),
        to: asCalendarDay(endOfMonth(current)),
      };
    }
    case "lastMonth": {
      const previous = subMonths(current, 1);
      return {
        from: startOfMonth(previous),
        to: asCalendarDay(endOfMonth(previous)),
      };
    }
    default: {
      const exhaustive: never = shortcut;
      throw new Error(`Unsupported date shortcut: ${exhaustive}`);
    }
  }
};

export const toLocalDateValue = (date: Date): string => {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
};

export const isSelectableDateRange = (
  range: DateRange | undefined,
  disabledDates: readonly Date[] = []
): boolean => {
  if (
    !range?.from ||
    !range.to ||
    isAfter(startOfDay(range.from), startOfDay(range.to))
  ) {
    return false;
  }
  return !disabledDates.some(
    (date) =>
      (isSameDay(date, range.from as Date) ||
        isAfter(startOfDay(date), startOfDay(range.from as Date))) &&
      (isSameDay(date, range.to as Date) ||
        isBefore(startOfDay(date), startOfDay(range.to as Date)))
  );
};

export const isDateDisabled = (
  date: Date,
  disabledDates: readonly Date[] = []
): boolean => disabledDates.some((disabled) => isSameDay(date, disabled));

export const rangeIncludesDisabledDate = (
  range: DateRange | undefined,
  disabledDates: readonly Date[] = []
): boolean => {
  if (!range?.from || !range.to) {
    return false;
  }
  return disabledDates.some(
    (date) =>
      (isSameDay(date, range.from as Date) ||
        isAfter(date, range.from as Date)) &&
      (isSameDay(date, range.to as Date) || isBefore(date, range.to as Date))
  );
};

export { addDays };
